import { Component, OnInit } from '@angular/core';
import { ActivatedRoute } from '@angular/router';
import { Company } from 'src/app/landing/models/company';
import { Application } from 'src/app/auth/Models/Application';
import { CompanyService } from 'src/app/service/company/company.service';
import { ApplicationService } from 'src/app/service/application/application.service';
import { AuthStateService } from 'src/app/shared/services/auth-state.service';

@Component({
  selector: 'app-edit-profile',
  templateUrl: './edit-profile.component.html',
  styleUrls: ['./edit-profile.component.css']
})
export class EditProfileComponent implements OnInit {
  companyId!: number;
  company!: Company;

  constructor(
    private readonly compService: CompanyService,
    private readonly appService: ApplicationService,
    private readonly route: ActivatedRoute,
    private readonly authState: AuthStateService
  ) {}

  ngOnInit(): void {
    const routeId = this.route.snapshot.paramMap.get('id');
    if (routeId) {
      this.companyId = Number(routeId);
    } else {
      const id = this.authState.id;
      this.companyId = id ?? 0;
    }
    if (this.companyId > 0) {
      this.compService.getCompanyById(this.companyId).subscribe((res: Company) => (this.company = res));
    }
  }

  get avatar(): string {
    return this.authState.initialsFromCompany(this.company);
  }

  logout(): void {
    this.authState.logout();
  }
}
